(()=>{
  const flat=(t)=>t.replace(/\s+/g,' ').trim();
  const rows=[...document.querySelectorAll('.nd-row')];
  const out=rows.map(r=>({
    name:flat(r.querySelector('.nd-skill-name').textContent),
    stats:flat(r.querySelector('.nd-stats').textContent),
    cells:[...r.querySelectorAll('.nd-cell')].map(c=>({
      cls:c.className,
      inertBadge:getComputedStyle(c.querySelector('.nd-inert-badge')).display,
      strike:getComputedStyle(c.querySelector('.nd-strike')).display,
      hollow:!!c.querySelector('.nd-glyph.nd-hollow')
    }))
  }));
  const nova=rows.find(r=>r.querySelector('.nd-skill-name').textContent.includes('Nova'));
  const b=nova.getBoundingClientRect();
  const page=document.querySelector('.nd-page').getBoundingClientRect();
  const capLab=document.querySelector('.nd-cap-label');
  const cs=(sel,prop)=>getComputedStyle(document.querySelector(sel))[prop];
  return JSON.stringify({
    rows:out,
    novaRect:{x:Math.round(b.x),y:Math.round(b.y),w:Math.round(b.width),h:Math.round(b.height)},
    pageRect:{x:Math.round(page.x),y:Math.round(page.y),w:Math.round(page.width),h:Math.round(page.height)},
    scale:getComputedStyle(document.getElementById('socket-screen')).getPropertyValue('--nd-s').trim(),
    capLabelPx:getComputedStyle(capLab).fontSize,
    statsPx:cs('.nd-stats','fontSize'),
    titlePx:cs('.nd-title','fontSize'),
    subPx:cs('.nd-skill-sub','fontSize'),
    docScrollW:document.documentElement.scrollWidth,
    winW:window.innerWidth, winH:window.innerHeight
  });
})()
